  "name": "Element Screenshot Tool",
  "version": "1.0",
  "description": "Click any element on a webpage to screenshot it using Canvas.",
  "permissions": [
    "activeTab",
    "scripting",
    "downloads"
  ],
  "background": {
    "service_worker": "background.js"
  },
  "content_scripts": [
    {
      "matches": ["<all_urls>"],
